def test_cosh_acos_acosh_is_zero_recursion():
    import pytest
    from sympy import cosh, acos, acosh, symbols
    i, g = symbols('i g')
    expr = cosh(acos(-i + acosh(-g + i)))
    try:
        result = expr.is_zero
    except RecursionError:
        pytest.fail("RecursionError raised when accessing is_zero")
    assert result in (True, False, None)
